    const fields = profile?.fields ?? [];
    const sheet = item.status === 'sheet_required' ? `<form method="post" action="/work/${encodeURIComponent(session.session_id)}/action" class="inline-actions"><input type="hidden" name="csrf" value="${escapeHtml(model.csrf)}"><input type="hidden" name="action" value="sheet"><input type="hidden" name="base_revision" value="${escapeHtml(session.revision)}"><input type="hidden" name="source_key" value="${escapeHtml(item.source_key)}"><label>${h('work.sheet')} <select name="sheet" required><option value="">${h('work.choose_sheet')}</option>${(item.sheets ?? []).map((entry) => `<option value="${escapeHtml(entry.name)}">${escapeHtml(entry.name)}${entry.rows == null ? '' : ` · ${h('work.rows_count', {count:format(entry.rows)})}`}</option>`).join('')}</select></label><button class="action-button">${h('work.use_sheet')}</button></form>` : '';
    const facts = profile ? renderFacts([[t('work.rows'), format(profile.rows)], [t('work.fields'), format(profile.columns)], [t('work.null_cells'), format(profile.null_cells)], [t('work.duplicates'), format(profile.duplicate_rows)], [t('work.sheet'), item.sheet ?? 'CSV']]) : '';
    const fieldRows = fields.length ? `<div class="data-work-table-wrap"><table class="data-work-table"><thead><tr><th>${h('work.field')}</th><th>${h('work.type')}</th><th>${h('work.nulls')}</th><th>${h('work.distinct')}</th><th>${h('work.date_range')}</th></tr></thead><tbody>${fields.map((field) => `<tr><td>${escapeHtml(field.name)}</td><td>${escapeHtml(field.inferred_type)}</td><td>${format(field.missing_count)}</td><td>${format(field.distinct_count)}</td><td>${escapeHtml(field.date_range ? `${field.date_range.minimum} – ${field.date_range.maximum}` : '—')}</td></tr>`).join('')}</tbody></table></div>` : '';
    const reconciliation = sourceReconciliation(session, item, model.csrf);
