  const option = (empty, selected = '', choices = fields) => `<option value="">${escapeHtml(empty)}</option>${choices.map((field) => `<option value="${escapeHtml(field)}" ${field === selected ? 'selected' : ''}>${escapeHtml(field)}</option>`).join('')}`;
